method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires class_name != ""
    requires extensions != []
    ensures result == class_name + "." + strongest_extension_name
    ensures strongest_extension_name in extensions
    ensures forall e :: e in extensions && e != strongest_extension_name ==> strength(e) < strength(strongest_extension_name)
{
    var strongest_extension_name := extensions[0];
    var max_strength := strength(strongest_extension_name);

    var i := 1;
    while i < |extensions|
        invariant 0 <= i <= |extensions|
        invariant max_strength == strength(strongest_extension_name)
        invariant strongest_extension_name in extensions
    {
        if strength(extensions[i]) > max_strength {
            strongest_extension_name := extensions[i];
            max_strength := strength(strongest_extension_name);
        }
        i := i + 1;
    }

    result := class_name + "." + strongest_extension_name;
}

function strength(extension: string): int
{
    var cap := 0;
    var sm := 0;
    var i := 0;
    while i < |extension|
        invariant 0 <= i <= |extension|
        invariant cap >= 0 && sm >= 0
    {
        if extension[i] >= 'A' && extension[i] <= 'Z' {
            cap := cap + 1;
        } else if extension[i] >= 'a' && extension[i] <= 'z' {
            sm := sm + 1;
        }
        i := i + 1;
    }
    return cap - sm;
}
